CREATE TABLE "encryption_keys" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "fingerprint" character varying NOT NULL, "version" character varying NOT NULL, "origin" character varying NOT NULL, "possession" character varying NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "encryption_keys_fingerprint_key" ON "encryption_keys" ("fingerprint");
